<script setup>
import {ref,watch,onMounted,onBeforeUnmount,nextTick,inject} from 'vue';import {useRoute} from 'vue-router';import {getArticleById,getRecommendArticleById} from '@/api/article';import Comment from '@/components/Comment/ModeratedComment.vue';import {user} from '@/store';import './reading.scss';
const site=inject('lin-site',ref({}));const route=useRoute(),post=ref(null),related=ref({recommend:[]}),error=ref(''),busy=ref(false),active=ref(''),progress=ref(0),copied=ref(false);let generation=0;
async function load(){const id=route.query.id||route.params.slug;if(!id){error.value='请从文章列表选择一篇文章。';return;}const n=++generation;busy.value=true;error.value='';post.value=null;try{const [p,r]=await Promise.all([getArticleById(id),getRecommendArticleById(id)]);if(n!==generation)return;post.value=p.result;related.value=r.result;await nextTick();update();document.title=post.value.title+' · '+(site.value.title||'Lin 的随手记');}catch(e){if(n===generation)error.value=e.message;}finally{if(n===generation)busy.value=false;}}
function update(){const body=document.querySelector('.reading-prose');if(!body)return;const box=body.getBoundingClientRect();progress.value=Math.round(Math.max(0,Math.min(100,(110-box.top)/Math.max(1,box.height-innerHeight+150)*100)));let last=post.value?.headings?.[0]?.id||'';for(const h of post.value?.headings||[])if(document.getElementById(h.id)?.getBoundingClientRect().top<170)last=h.id;active.value=last;}
async function copy(){try{await navigator.clipboard.writeText(location.origin+'/blog/'+post.value.slug);copied.value=true;}catch{copied.value=false;}}
watch(()=>route.query.id||route.params.slug,load,{immediate:true});onMounted(()=>addEventListener('scroll',update,{passive:true}));onBeforeUnmount(()=>{generation++;removeEventListener('scroll',update);});
</script>
<template><main class="reading-page"><p v-if="error" role="alert">{{error}} <RouterLink to="/home">返回随手记</RouterLink></p><el-skeleton v-if="busy" :rows="10" animated/><template v-if="post"><header class="reading-heading"><div class="reading-kicker"><RouterLink to="/home">随手记</RouterLink><span>／</span><RouterLink to="/category">{{post.category}}</RouterLink><span class="reading-number">NOTES FROM LIN</span></div><h1>{{post.title}}</h1><p class="reading-deck">{{post.excerpt}}</p><div class="reading-byline"><img :src="post.authorAvatar||'/favicon.svg'" alt="作者头像"/><b>{{post.authorName}}</b><time>{{post.createdAt}}</time><span>约 {{Math.max(1,Math.ceil(post.content.length/450))}} 分钟阅读</span><a v-if="user().getUserInfo.role==='admin'" :href="'/admin/article/editArticle?articleId='+post.recordId">编辑本文 ↗</a></div></header><figure v-if="post.article_cover" class="reading-cover"><img :src="post.article_cover" alt="文章封面"/></figure><div class="reading-layout"><article class="reading-paper"><div class="source-prose reading-prose" v-html="post.html"/><footer class="reading-signature"><div><span>WRITTEN BY</span><h3>{{post.authorName}}</h3><p>{{post.authorBio||'写一点代码，记一些日常，也认真喜欢故事。'}}</p></div><button @click="copy">{{copied?'链接已复制 ✓':'分享这篇文章 ↗'}}</button><small>{{post.type===1?'原创文章，转载时请注明作者与出处。':'转载 / 翻译文章，原作版权归原作者。'}} <a v-if="post.origin_url" :href="post.origin_url" target="_blank" rel="noopener noreferrer">查看原文 ↗</a></small></footer><nav class="reading-neighbors"><RouterLink v-if="related.previous?.id" :to="'/blog/'+related.previous.id"><span>上一篇</span><strong>← {{related.previous.article_title}}</strong></RouterLink><RouterLink v-if="related.next?.id" :to="'/blog/'+related.next.id"><span>下一篇</span><strong>{{related.next.article_title}} →</strong></RouterLink></nav><Comment :id="post.id" type="article" :author-id="post.author_id"/></article><aside class="reading-aside"><section class="reading-toc"><div><b>这一篇的目录</b><span>{{progress}}%</span></div><div class="toc-meter"><i :style="{width:progress+'%'}"/></div><a v-for="h in post.headings" :key="h.id" :href="'#'+h.id" :class="{active:active===h.id,nested:h.level!=='h1'&&h.level!=='h2'}">{{h.text}}</a><p v-if="!post.headings?.length">慢慢读，不必赶进度。</p></section><section class="reading-related"><span>还可以读</span><RouterLink v-for="r in related.recommend" :key="r.id" :to="'/blog/'+r.id"><strong>{{r.article_title}}</strong><small>{{r.createdAt}} · {{r.category}}</small></RouterLink></section></aside></div></template></main></template>
